query:
mutation ScheduleMaintenanceTasksWithParams($tasks: [MaintenanceTaskInput!]!, $schedule: ScheduleInput!) {
  scheduleMaintenanceTasks(tasks: $tasks, schedule: $schedule) {
    success
    scheduledTasks {
      id
      type
      description
      estimatedDuration
      priority
      dependencies
      resources
    }
    schedule {
      startTime
      endTime
      frequency
      nextExecution
    }
    impact {
      affectedTables
      estimatedDowntime
      userImpact
      rollbackPlan
    }
    monitoring {
      checkpoints
      alertThresholds
      notificationChannels
    }
  }
}
